INSERT OR REPLACE INTO "comments" ("id", "lesson_id", "idea_id", "author", "author_email", "author_image", "text", "time") VALUES ('cmt_demo_dl1_2', 'dl-1', NULL, 'คุณครูผู้สอนศิลปะ (Art Teacher)', 'teacher.art@wts.ac.th', '', 'ยอดเยี่ยมมากครับพัสกร การทำ Stippling ต้องอาศัยความสม่ำเสมอของน้ำหนักมือ ลองฝึกควบคุมระยะห่างของจุดในส่วนไฮไลท์ดูนะครับ เมื่อเสร็จแล้วนำส่งในระบบส่งงานได้เลยครับ 👍', '2026-09-15 15:10:00');
