INSERT OR REPLACE INTO "downloads" ("id", "title", "description", "category", "grade", "file_name", "file_size", "file_url", "downloads_count", "order_index", "created_at") VALUES ('dl-1', 'ใบงานที่ 1: พื้นฐาน เรื่องของจุดและเส้นสร้างสรรค์', 'เรียนรู้การจัดวาง การสร้างน้ำหนัก และจังหวะของจุดเพื่อสร้างลวดลายและมิติในงานศิลปะเบื้องต้น', 'ใบงาน', 'all', 'worksheet_01_points_and_lines.pdf', '1.4 MB', 'https://pdfobject.com/pdf/sample.pdf', 344, 1, '2026-09-14 10:07:19');
INSERT OR REPLACE INTO "downloads" ("id", "title", "description", "category", "grade", "file_name", "file_size", "file_url", "downloads_count", "order_index", "created_at") VALUES ('dl-2', 'ใบงานที่ 2: การลงน้ำหนักแสงเงา 7 ระดับ (Value Scale)', 'แบบฝึกปฏิบัติการลงน้ำหนัก 7 ระดับ ด้วยดินสอดำ EE สำหรับนักเรียนเริ่มต้นสร้างความสมจริง', 'ใบงาน', 'all', 'worksheet_02_value_scale_shading.pdf', '2.1 MB', 'https://www.w3.org/WAI/ER/tests/xhtml/testfiles/resources/pdf/dummy.pdf', 893, 2, '2026-09-14 10:07:19');
INSERT OR REPLACE INTO "downloads" ("id", "title", "description", "category", "grade", "file_name", "file_size", "file_url", "downloads_count", "order_index", "created_at") VALUES ('dl-3', 'ใบงานที่ 3: การเขียนภาพทัศนียภาพ 1 จุด และ 2 จุด (Perspective Drawing)', 'หลักการลากเส้นระดับสายตา (Eye Level) และจุดรวมสายตา (Vanishing Point) พร้อมตารางฝึกร่างแบบ', 'ใบงาน', 'm4', 'worksheet_03_perspective_drawing.pdf', '3.1 MB', 'https://pdfobject.com/pdf/sample.pdf', 156, 3, '2026-09-14 10:07:19');
INSERT OR REPLACE INTO "downloads" ("id", "title", "description", "category", "grade", "file_name", "file_size", "file_url", "downloads_count", "order_index", "created_at") VALUES ('dl-4', 'ใบความรู้: ทฤษฎีสีและวงจรสีสากล 12 สี (Color Theory & Wheel)', 'สรุปแม่สีขั้นที่ 1, 2, 3 วรรณะสีอุ่น-เย็น และคู่สีตรงข้าม พร้อมตัวอย่างการผสมสีน้ำ', 'ใบความรู้', 'all', 'handbook_color_theory_wheel.pdf', '2.8 MB', 'https://www.w3.org/WAI/ER/tests/xhtml/testfiles/resources/pdf/dummy.pdf', 521, 4, '2026-09-14 10:07:19');
INSERT OR REPLACE INTO "downloads" ("id", "title", "description", "category", "grade", "file_name", "file_size", "file_url", "downloads_count", "order_index", "created_at") VALUES ('dl-5', 'เกณฑ์การให้คะแนนผลงานทัศนศิลป์ (Art Rubric Assessment Score)', 'คู่มือเกณฑ์การประเมินความคิดสร้างสรรค์ ความประณีต เทคนิคการใช้สื่อ และการสื่อความหมาย', 'คู่มือ', 'all', 'art_rubric_assessment_guide.pdf', '850 KB', 'https://pdfobject.com/pdf/sample.pdf', 210, 5, '2026-09-14 10:07:19');
INSERT OR REPLACE INTO "downloads" ("id", "title", "description", "category", "grade", "file_name", "file_size", "file_url", "downloads_count", "order_index", "created_at") VALUES ('dl-6', 'คู่มือนักเรียน: กฎความปลอดภัยและการดูแลรักษาอุปกรณ์ในห้องปฏิบัติการศิลปะ', 'ระเบียบการยืม-คืนพู่กัน การล้างจานสี การทิ้งสารเคมี และข้อควรปฏิบัติในห้อง Art Room', 'คู่มือ', 'all', 'art_room_safety_and_rules.pdf', '1.2 MB', 'https://www.w3.org/WAI/ER/tests/xhtml/testfiles/resources/pdf/dummy.pdf', 285, 6, '2026-09-14 10:07:19');
INSERT OR REPLACE INTO "testimonials" ("id", "name", "university", "quote", "image_url", "univ_image_url", "created_at") VALUES ('1789477780811', 'พี่บอย (ศิลปกรรมศาสตร์)', 'มหาวิทยาลัยศิลปากร', 'การเรียนที่ Art Room ทำให้ผมได้ค้นพบเทคนิคและสไตล์ของตัวเอง อาจารย์ให้คำแนะนำที่ตรงจุดและเอาใจใส่มากครับ จนสามารถสอบติดคณะที่ฝันได้!', 'https://ui-avatars.com/api/?name=Boy&background=E5E7EB&color=374151&size=200', 'https://ui-avatars.com/api/?name=SU&background=15803d&color=fff&size=100', '2026-09-15T13:09:40.811Z');
INSERT OR REPLACE INTO "testimonials" ("id", "name", "university", "quote", "image_url", "univ_image_url", "created_at") VALUES ('1789477806764', 'พี่ยูริกะ (สถาปัตยกรรมศาสตร์)', 'จุฬาลงกรณ์มหาวิทยาลัย', 'ไม่เคยมีพื้นฐานมาก่อนเลยค่ะ แต่ที่นี่สอนตั้งแต่พื้นฐานจนสามารถทำพอร์ตฟอลิโอที่โดดเด่นได้ บรรยากาศเป็นกันเองมาก ๆ ค่ะ', 'https://ui-avatars.com/api/?name=Yurika&background=E5E7EB&color=374151&size=200', 'https://ui-avatars.com/api/?name=CU&background=db2777&color=fff&size=100', '2026-09-15T13:10:06.764Z');
INSERT OR REPLACE INTO "testimonials" ("id", "name", "university", "quote", "image_url", "univ_image_url", "created_at") VALUES ('1789477909860', 'พี่พัน', 'มศว', 'รักเรียนมาก', '/uploads/testimonials/testimonials_1789477909860_image_url.jpg', '/uploads/testimonials/testimonials_1789477909860_univ_image_url.png', '2026-09-15T13:11:49.864Z');
INSERT OR REPLACE INTO "activities" ("id", "title", "date", "description", "image_url", "images", "created_at", "time", "location", "category", "color") VALUES ('1789478831614', 'กิจกรรมสอนวาดเส้นพื้นฐานสำหรับเด็กประถม', '12 ตุลาคม 2566', 'เรียนรู้วิธีการลากเส้น การลงน้ำหนัก และการกะระยะเพื่อการวาดภาพเบื้องต้น เด็กๆ ได้สนุกสนานกับการสร้างสรรค์ผลงานชิ้นแรกของตัวเอง', 'https://images.unsplash.com/photo-1599423300746-b62533397364?w=800&q=80', '"[\"https://images.unsplash.com/photo-1599423300746-b62533397364?w=800&q=80\",\"https://images.unsplash.com/photo-1513364776144-60967b0f80df?w=800&q=80\",\"https://images.unsplash.com/photo-1518998053401-87895085d7b6?w=800&q=80\"]"', '2026-09-15T13:27:11.614Z', NULL, NULL, NULL, NULL);
INSERT OR REPLACE INTO "activities" ("id", "title", "date", "description", "image_url", "images", "created_at", "time", "location", "category", "color") VALUES ('1789478841673', 'ประกวดศิลปะเยาวชนแห่งชาติ', '5 พฤศจิกายน 2566', 'ขอแสดงความยินดีกับน้องๆ ที่ได้รับรางวัลจากการประกวดศิลปะในหัวข้อ ''อนาคตของฉัน'' ผลงานของทุกคนยอดเยี่ยมมาก', 'https://images.unsplash.com/photo-1605721911519-3dfeb3be25e7?w=800&q=80', '"[\"https://images.unsplash.com/photo-1520697830682-8986847c11f4?w=800&q=80\",\"https://images.unsplash.com/photo-1605721911519-3dfeb3be25e7?w=800&q=80\",\"/uploads/activities/activities_1789478841673_images_1.jpg\"]"', '2026-09-15T13:27:21.673Z', NULL, NULL, NULL, NULL);
INSERT OR REPLACE INTO "activities" ("id", "title", "date", "description", "image_url", "images", "created_at", "time", "location", "category", "color") VALUES ('1789479082290', '5555', '12/20', '้่าเด', '/uploads/activities/activities_1789479082290_image_url.jpg', '"[\"/uploads/activities/activities_1789479082290_images_1.jpg\",\"/uploads/activities/activities_1789479082290_images_2.jpg\",\"/uploads/activities/activities_1789479082290_images_3.jpg\",\"/uploads/activities/activities_1789479082290_images_4.jpg\"]"', '2026-09-15T13:31:22.299Z', NULL, NULL, NULL, NULL);
