INSERT OR REPLACE INTO "submissions" ("id", "assignment_id", "student_id", "student_name", "classroom", "image_url", "images", "file_url", "file_name", "external_link", "concept", "score", "feedback", "status", "is_late", "submitted_at", "updated_at") VALUES ('sub_1789720743263_35441', 'assign_1789622111791', '35441', 'นายเอกนรินทร์ วรอินทร์', 'ม.6/6', NULL, NULL, NULL, NULL, 'https://canva.com/design/test', 'ทดสอบส่งงานระบบแจ้งเตือนอีเมลอัตโนมัติ (Automated Notification Test)', NULL, NULL, 'pending', 1, '2026-09-18T08:39:03.263Z', NULL);
INSERT OR REPLACE INTO "quizzes" ("id", "code", "title", "grade_level", "description", "total_questions", "max_score", "time_limit_minutes", "is_active", "created_at", "target_classrooms") VALUES ('quiz_m3_pretest', 'ศ23101', 'แบบทดสอบก่อนเรียน: วิชาศิลปะ (ทัศนศิลป์) ชั้น ม.3', 'ม.3', 'แบบทดสอบวัดความรู้พื้นฐานก่อนเรียน สาระทัศนศิลป์ ระดับชั้นมัธยมศึกษาปีที่ 3 ตามหลักสูตรแกนกลางการศึกษาขั้นพื้นฐาน (จำนวน 20 ข้อ เวลา 30 นาที)', 20, 20, 30, 1, '2026-09-16 12:52:56', NULL);
INSERT OR REPLACE INTO "quizzes" ("id", "code", "title", "grade_level", "description", "total_questions", "max_score", "time_limit_minutes", "is_active", "created_at", "target_classrooms") VALUES ('quiz_m4_pretest', 'ศ31101', 'แบบทดสอบก่อนเรียน: วิชาศิลปะ (ทัศนศิลป์) ชั้น ม.4', 'ม.4', 'แบบทดสอบวัดความรู้พื้นฐานและกระบวนทัศน์ทางทัศนศิลป์ ระดับชั้นมัธยมศึกษาปีที่ 4 ตามหลักสูตรแกนกลางการศึกษาขั้นพื้นฐาน (จำนวน 20 ข้อ เวลา 30 นาที)', 20, 20, 30, 1, '2026-09-16 12:52:56', NULL);
INSERT OR REPLACE INTO "quizzes" ("id", "code", "title", "grade_level", "description", "total_questions", "max_score", "time_limit_minutes", "is_active", "created_at", "target_classrooms") VALUES ('quiz_m3_formative_elements', 'ศ23101', 'แบบทดสอบเก็บคะแนน: เรื่องทัศนธาตุและการจัดองค์ประกอบศิลป์', 'ม.3', 'แบบทดสอบเก็บคะแนนระหว่างเรียน 10 คะแนน 15 นาที เรื่องทัศนธาตุและหลักการออกแบบ', 10, 10, 15, 1, '2026-09-17 07:34:56', NULL);
INSERT OR REPLACE INTO "quizzes" ("id", "code", "title", "grade_level", "description", "total_questions", "max_score", "time_limit_minutes", "is_active", "created_at", "target_classrooms") VALUES ('quiz_m4_formative_arthistory', 'ศ31101', 'แบบทดสอบเก็บคะแนน: เรื่องประวัติศาสตร์และรูปแบบศิลปะสากล', 'ม.4', 'แบบทดสอบเก็บคะแนนระหว่างเรียน 10 คะแนน 15 นาที เรื่องยุคสมัยและรูปแบบศิลปะสากล', 10, 10, 15, 1, '2026-09-17 07:34:56', NULL);
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m3_01', 'quiz_m3_pretest', 1, 'ข้อใดคือความหมายที่ถูกต้องที่สุดของ ''ทัศนศิลป์'' (Visual Arts) ตามหลักสุนทรียศาสตร์?', 'ศิลปะที่รับรู้ได้ด้วยการมองเห็นและการสัมผัสทางกายภาพ', 'ศิลปะที่เน้นการฟังเสียงและการเคลื่อนไหวบนเวที', 'วรรณกรรมและบทกวีที่ถ่ายทอดผ่านภาษาเขียน', 'การแสดงดนตรีสากลและนาฏศิลป์พื้นบ้าน', 'A', 'ทัศนศิลป์ (Visual Arts) คือศิลปะที่สามารถรับรู้และชื่นชมความงามได้ผ่านประสาทสัมผัสทางสายตา (การมองเห็น) และพื้นผิวสัมผัส', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m3_02', 'quiz_m3_pretest', 2, 'การวาดภาพทัศนียภาพแบบ 1 จุดรวมสายตา (One-point Perspective) เหมาะสมที่สุดกับการเขียนภาพทัศนียภาพในข้อใด?', 'การมองเห็นมุมตึกด้านนอก', 'การมองตามแนวยาวของถนนหรือทางเดินในอุโมงค์', 'การมองสิ่งก่อสร้างจากมุมมองตานก (Bird''s Eye View)', 'การมองวัตถุรูปทรงกลมบนโต๊ะ', 'B', 'การวาด Perspective 1 จุด เหมาะกับการมองวัตถุหรือสถานที่ที่ด้านหน้าขนานกับระนาบสายตา เช่น แนวรางรถไฟ ทางเดิน หรือห้องตอนลึก', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m3_03', 'quiz_m3_pretest', 3, 'หากต้องการให้ผลงานภาพวาดมีความรู้สึกสงบนิ่ง มั่นคง และกว้างขวาง ควรเน้นการใช้เส้นประเภทใดเป็นหลัก?', 'เส้นแนวนอน (Horizontal Line)', 'เส้นเฉียง (Diagonal Line)', 'เส้นซิกแซก (Zigzag Line)', 'เส้นโค้งก้นหอย (Spiral Line)', 'A', 'เส้นแนวนอนให้ความรู้สึกราบเรียบ กว้างขวาง สงบนิ่ง มั่นคง เปรียบเสมือนระนาบผิวน้ำหรือเส้นขอบฟ้า', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m3_04', 'quiz_m3_pretest', 4, 'คู่สีตรงข้าม (Complementary Colors) ในวงจรสีข้อใดที่สร้างความขัดแย้งและตัดกันอย่างชัดเจนที่สุด?', 'สีแดง กับ สีส้ม', 'สีเหลือง กับ สีม่วง', 'สีน้ำเงิน กับ สีเขียว', 'สีฟ้า กับ สีขาว', 'B', 'สีเหลืองและสีม่วงเป็นคู่สีตรงข้ามกันโดยตรงในวงจรสี 12 สี ให้ความรู้สึกตัดกันและดึงดูดสายตาอย่างรุนแรง', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m3_05', 'quiz_m3_pretest', 5, 'ข้อใดอธิบายความแตกต่างระหว่าง ''รูปร่าง (Shape)'' และ ''รูปทรง (Form)'' ได้ถูกต้องที่สุด?', 'รูปร่างมี 3 มิติ แต่รูปทรงมี 2 มิติ', 'รูปร่างมีเพียงความกว้างและความยาว ส่วนรูปทรงมีความหนาหรือความลึกเพิ่มขึ้นมา', 'รูปร่างเกิดจากธรรมชาติ รูปทรงเกิดจากมนุษย์สร้างขึ้น', 'รูปร่างมีน้ำหนักแสงเงา ส่วนรูปทรงไม่มีแสงเงา', 'B', 'รูปร่าง (Shape) เป็น 2 มิติ ประกอบด้วยความกว้างและความยาว ส่วนรูปทรง (Form) มี 3 มิติ ประกอบด้วยความกว้าง ความยาว และความลึกหรือความหนา', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m3_06', 'quiz_m3_pretest', 6, 'เทคนิคการระบายสีน้ำแบบ ''เปียกบนเปียก (Wet-on-wet)'' มักให้ผลลัพธ์ของภาพเป็นอย่างไร?', 'ขอบภาพคมชัด สีเข้มทึบ', 'สีกลมกลืนฟุ้งกระจายอย่างนุ่มนวลและเป็นธรรมชาติ', 'เกิดรอยขูดขีดและพื้นผิวหยาบด้าน', 'สีแห้งเร็วและไม่ซึมเข้าหากัน', 'B', 'เทคนิคเปียกบนเปียกคือการลงน้ำบนกระดาษก่อนแล้วแต้มสีลงไป ทำให้สีไหลซึมและฟุ้งกระจาย เหมาะกับการระบายท้องฟ้า หมอก หรือผิวน้ำ', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m3_07', 'quiz_m3_pretest', 7, 'การจัดองค์ประกอบศิลป์แบบ ''ความสมดุลแบบสองข้างไม่เท่ากัน (Asymmetrical Balance)'' ให้ผลทางความรู้สึกอย่างไร?', 'เป็นทางการ หยุดนิ่ง และน่าเบื่อ', 'เคลื่อนไหว มีชีวิตชีวา น่าตื่นเต้นแต่ยังรู้สึกสมดุลทางสายตา', 'เอียง ไม่มีความมั่นคงและสายตามองหาจุดเด่นไม่ได้', 'เคร่งขรึม เหมือนภาพตราสัญลักษณ์ราชการ', 'B', 'ความสมดุลแบบอสมมาตร ทั้งสองข้างมีรูปร่างและขนาดต่างกันแต่น้ำหนักทางสายตาเท่ากัน ทำให้ภาพดูมีชีวิตชีวาและไม่น่าเบื่อ', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m3_08', 'quiz_m3_pretest', 8, 'ในกระบวนการเขียนภาพแสงเงา ส่วนที่มืดที่สุดบนตัววัตถุที่แสงส่องไปไม่ถึงโดยตรง เรียกว่าอะไร?', 'เงาตกทอด (Cast Shadow)', 'แสงสะท้อน (Reflected Light)', 'เงามืดแกนกลาง (Core Shadow)', 'แสงไฮไลท์ (Highlight)', 'C', 'Core Shadow (เงามืดแกนกลาง) คือแถบเงาที่เข้มที่สุดบนระนาบของวัตถุ ส่วน Cast Shadow คือเงาที่ทอดลงบนพื้นผิวข้างเคียง', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m3_09', 'quiz_m3_pretest', 9, 'ลายไทยแม่บทพื้นฐาน 4 หมวด ได้แก่ข้อใด?', 'ลายกระจัง, ลายประจำยาม, ลายหน้ากระดาน, ลายก้านขด', 'ลายกนก, ลายนารายณ์, ลายหงส์, ลายสิงห์', 'ลายกระหนก, ลายนารี, ลายกระบี่, ลายคชะ', 'ลายพุ่มข้าวบิณฑ์, ลายดาวเพดาน, ลายรักร้อย, ลายเฟื่อง', 'C', 'ลายไทยแม่บท 4 หมวด คือ กนก (พืชพันธุ์ไม้เปลวไฟ), นารี (มนุษย์ เทวดา นางรำ), กระบี่ (ลิง ยักษ์ วานร) และคชะ (สัตว์ต่างๆ)', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m3_10', 'quiz_m3_pretest', 10, 'ภาพพิมพ์ประเภทใดที่ใช้หลักการแกะแม่พิมพ์ไม้หรือแผ่นยาง (Linocut) โดยส่วนที่นูนขึ้นมาจะเป็นส่วนที่ติดหมึกพิมพ์?', 'ภาพพิมพ์ร่องลึก (Intaglio)', 'ภาพพิมพ์ผิวนูน (Relief Printing)', 'ภาพพิมพ์ตะแกรงไหม (Silk Screen)', 'ภาพพิมพ์หิน (Lithography)', 'B', 'ภาพพิมพ์ผิวนูน (Relief Printing) คือการแกะส่วนที่ไม่ต้องการให้เป็นร่อง และให้ส่วนนูนรับหมึกพิมพ์แล้วกดลงบนกระดาษ', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m3_11', 'quiz_m3_pretest', 11, 'เทคนิค ''การแรเงาด้วยการแต้มจุด (Stippling)'' ใช้หลักการใดในการสร้างมิติน้ำหนักเข้ม-สว่าง?', 'การขีดเส้นตัดกันเป็นตาราง', 'ความหนาแน่นและระยะห่างของจุด', 'การใช้นิ้วเกลี่ยผงดินสอ', 'การใช้ยางลบปาดไฮไลท์', 'B', 'เทคนิค Stippling จุดที่ชิดแน่นจะทำให้เกิดน้ำหนักเข้มมืด ส่วนจุดที่ห่างกระจายจะให้ความรู้สึกสว่างโปร่ง', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m3_12', 'quiz_m3_pretest', 12, 'งานประติมากรรมประเภท ''นูนต่ำ (Bas-relief)'' มีลักษณะเด่นอย่างไร?', 'มองเห็นได้รอบด้าน 360 องศา', 'นูนขึ้นมาจากแผ่นหลังเพียงเล็กน้อย มองเห็นได้เฉพาะด้านหน้า เช่น เหรียญกษาปณ์', 'นูนขึ้นมาเกินกว่าครึ่งหนึ่งของรูปทรงจริง', 'เจาะทะลุเป็นช่องว่างโปร่งแสง', 'B', 'ประติมากรรมนูนต่ำจะนูนขึ้นมาจากแผ่นรองเพียงเล็กน้อย เช่น เหรียญพระ หรือลวดลายบนเหรียญบาท', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m3_13', 'quiz_m3_pretest', 13, 'หากนักเรียนต้องการออกแบบโปสเตอร์รณรงค์อนุรักษ์สิ่งแวดล้อมเพื่อสื่อสารเรื่องความอุดมสมบูรณ์และความสดชื่น ควรเลือกใช้โทนสีใดเป็นหลัก?', 'สีโทนร้อน เช่น ส้ม-แดง', 'สีโทนเย็น เช่น เขียว-ฟ้า', 'สีโมโนโครม ขาว-ดำ', 'สีทอง-เงินเมทัลลิก', 'B', 'วรรณะสีเย็น เช่น สีเขียวและสีฟ้า ให้ความรู้สึกสงบ ร่มเย็น สดชื่น สะอาด และเชื่อมโยงกับธรรมชาติโดยตรง', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m3_14', 'quiz_m3_pretest', 14, 'จิตรกรรมฝาผนังไทยประเพณีดั้งเดิมในอุโบสถมักใช้วิธีการจัดองค์ประกอบภาพในลักษณะใด?', 'การวาดแบบ Perspective ทัศนียภาพลึกตามหลักวิทยาศาสตร์ตะวันตก', 'การจัดภาพแบบมองจากมุมสูง (Bird''s Eye View) และระบายสีแบนตัดเส้น (Flat Tone)', 'การวาดภาพแบบไม่ใช้วรรณะสีเลย', 'การใช้กล้องถ่ายภาพฉายขึ้นผนัง', 'B', 'จิตรกรรมไทยประเพณีดั้งเดิมใช้มุมมองแบบ Bird''s eye view เล่าเรื่องเป็นชั้นๆ ระบายสีแบบ 2 มิติแบนตัดเส้น ไม่เน้นแสงเงาสมจริงแบบตะวันตก', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m3_15', 'quiz_m3_pretest', 15, 'หลักการออกแบบที่ทำให้สายตาของผู้ดูพุ่งไปยังส่วนสำคัญที่สุดของภาพเป็นอันดับแรก เรียกว่าอะไร?', 'ความกลมกลืน (Harmony)', 'จุดสนใจ หรือจุดเด่น (Focal Point / Emphasis)', 'สัดส่วน (Proportion)', 'จังหวะ (Rhythm)', 'B', 'Focal Point หรือการเน้นจุดเด่น คือการสร้างส่วนสำคัญในภาพให้สะดุดตาและดึงดูดความสนใจอันดับแรก', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m3_16', 'quiz_m3_pretest', 16, 'วัสดุในข้อใดต่อไปนี้จัดเป็น ''สีทึบแสง (Opaque Color)'' ที่สามารถระบายสีอ่อนทับสีเข้มได้?', 'สีน้ำ (Water Color)', 'สีโปสเตอร์ (Poster Color)', 'สีย้อมผ้า (Dye)', 'สีหมึกซึม (Ink)', 'B', 'สีโปสเตอร์เป็นสีผสมแป้ง มีคุณสมบัติทึบแสง แห้งเร็ว สามารถระบายทับซ้อนกันได้ ต่างจากสีน้ำที่เป็นสีโปร่งแสง', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m3_17', 'quiz_m3_pretest', 17, 'เมื่อนำสีคู่ตรงข้าม เช่น สีแดงและสีเขียว มาผสมรวมกันในปริมาณที่เท่ากัน จะได้ผลลัพธ์เป็นสีอะไร?', 'สีขาวบริสุทธิ์', 'สีดำ หรือสีน้ำตาลหม่น', 'สีส้มสว่าง', 'สีม่วงเปล่งประกาย', 'B', 'การผสมสีคู่ตรงข้ามเข้าด้วยกันจะลดค่าความสดของสี (Hue Saturation) ทำให้ได้สีน้ำตาลหม่น เทา หรือดำ', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m3_18', 'quiz_m3_pretest', 18, 'ข้อใดเป็นขั้นตอนแรกที่ถูกต้องที่สุดในการสร้างสรรค์ผลงานทัศนศิลป์?', 'การลงสีน้ำหนักจริงทันที', 'การตัดเส้นด้วยปากกาหมึกซึม', 'การกำหนดแนวคิด (Concept) และร่างภาพโครงสร้างคร่าวๆ', 'การใส่กรอบรูปภาพ', 'C', 'ขั้นตอนแรกของการทำงานศิลปะคือการวางแนวคิด การหาข้อมูล และการร่างภาพคร่าวๆ (Thumbnail Sketch) เพื่อจัดวางองค์ประกอบ', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m3_19', 'quiz_m3_pretest', 19, 'การประเมินและวิจารณ์ผลงานศิลปะมีจุดประสงค์หลักเพื่อสิ่งใด?', 'เพื่อจับผิดข้อบกพร่องและตัดสินให้คะแนนตก', 'เพื่อทำความเข้าใจคุณค่า ความหมาย และนำข้อคิดเห็นไปพัฒนาฝีมือสร้างสรรค์ต่อไป', 'เพื่อเปรียบเทียบว่าผลงานใครแพงกว่ากัน', 'เพื่อให้ศิลปินหยุดสร้างผลงานแปลกใหม่', 'B', 'การวิจารณ์ศิลปะมีเป้าหมายเพื่อชื่นชมคุณค่า เข้าใจเจตนารมณ์ของศิลปิน และแลกเปลี่ยนมุมมองเพื่อพัฒนาการเรียนรู้', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m3_20', 'quiz_m3_pretest', 20, 'คำว่า ''ทัศนศิลป์ (Visual Arts)'' หมายถึงศิลปะที่รับรู้ได้ผ่านทางประสาทสัมผัสส่วนใดเป็นสำคัญ?', 'การได้ยิน (หู)', 'การดมกลิ่น (จมูก)', 'การมองเห็น (ตา)', 'การลิ้มรส (ลิ้น)', 'C', 'ทัศนศิลป์ มาจากคำว่า ทัศนะ (การมองเห็น) + ศิลปะ หมายถึงศิลปะที่รับรู้ชื่นชมได้ด้วยการมองเห็นและการสัมผัส', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m4_01', 'quiz_m4_pretest', 1, 'ทฤษฎีสุนทรียศาสตร์ที่เน้นตัดสินคุณค่าของงานศิลปะจาก ''ความเหมือนจริงของธรรมชาติและการเลียนแบบรูปลักษณ์ภายนอก'' ตรงกับทฤษฎีใด?', 'ทฤษฎีรูปทรงนิยม (Formalism)', 'ทฤษฎีเลียนแบบนิยม (Imitationalism / Mimetic Theory)', 'ทฤษฎีอารมณ์นิยม (Emotionalism)', 'ทฤษฎีเครื่องมือนิยม (Instrumentalism)', 'B', 'Imitationalism หรือทฤษฎีเลียนแบบธรรมชาติ เชื่อว่าศิลปะที่ดีต้องมีความเหมือนจริงตามที่สายตามองเห็นในธรรมชาติ', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m4_02', 'quiz_m4_pretest', 2, 'ในกระบวนการวิจารณ์ผลงานศิลปะ 4 ขั้นตอนตามหลักการของ Edmund Feldman ขั้นตอนที่มุ่งค้นหา ''ความสัมพันธ์ของเส้น สี แสงเงา และหลักการจัดองค์ประกอบ'' คือขั้นตอนใด?', 'ขั้นระบุข้อมูลและพรรณนา (Description)', 'ขั้นวิเคราะห์ (Formal Analysis)', 'ขั้นตีความหมาย (Interpretation)', 'ขั้นประเมินคุณค่า (Judgement / Evaluation)', 'B', 'ขั้นวิเคราะห์ (Analysis) มุ่งศึกษาการจัดวางทัศนธาตุและหลักการออกแบบว่าสัมพันธ์กันอย่างไร ทำให้เกิดจุดเด่นและความกลมกลืนอย่างไร', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m4_03', 'quiz_m4_pretest', 3, 'ศิลปินกลุ่มอิมเพรสชันนิสม์ (Impressionism) เช่น โคลด โมเนต์ (Claude Monet) ให้ความสำคัญสูงสุดกับสิ่งใดในงานจิตรกรรม?', 'เรื่องเล่าทางศาสนาและตำนานเทพเจ้ากรีก', 'การจับภาพความประทับใจของแสงและสีสันของบรรยากาศในชั่วขณะเวลาจริง (En plein air)', 'การตัดเส้นขอบวัตถุให้คมชัดและลงสีเรียบแบน', 'ภาพความฝันและจิตใต้สำนึกของมนุษย์', 'B', 'Impressionism ให้ความสำคัญกับแสงแดดและสีสันที่เปลี่ยนแปลงไปในแต่ละช่วงเวลา นิยมออกไปวาดภาพกลางแจ้ง (Plein Air) ด้วยฝีแปรงรวดเร็ว', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m4_04', 'quiz_m4_pretest', 4, 'ลัทธิคิวบิสม์ (Cubism) ที่ริเริ่มโดย ปาโบล ปิกัสโซ (Pablo Picasso) มีแนวคิดการปฏิวัติการมองเห็นอย่างไร?', 'การเลียนแบบธรรมชาติให้เหมือนจริงแบบภาพถ่าย', 'การคลี่คลายรูปทรงออกเป็นเรขาคณิตและแสดงวัตถุหลายมุมมองพร้อมกันในระนาบเดียว', 'การใช้หยดสีราดลงบนผืนผ้าใบแบบไร้เจตนา', 'การนำสินค้าในซูเปอร์มาร์เก็ตมาจัดแสดง', 'B', 'Cubism ปฏิเสธระบบทัศนียภาพแบบดั้งเดิม โดยการถอดรหัสรูปทรงเป็นเรขาคณิตและนำเสนอมุมมองต่างๆ (Multiple Perspectives) พร้อมกัน', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m4_05', 'quiz_m4_pretest', 5, 'ผลงานจิตรกรรม ''The Starry Night'' ของ วินเซนต์ แวน โก๊ะ (Vincent van Gogh) สะท้อนรูปแบบของลัทธิใดเด่นชัดที่สุด?', 'ลัทธิคลาสสิกใหม่ (Neoclassicism)', 'ลัทธิโพสต์-อิมเพรสชันนิสม์ (Post-Impressionism / Expression of Emotion)', 'ลัทธิมินิมอล (Minimalism)', 'ลัทธิดาดา (Dadaism)', 'B', 'Van Gogh เป็นศิลปินคนสำคัญในกลุ่ม Post-Impressionism ที่ใช้เส้นสายคดเคี้ยว รอยแปรงหนา และสีสันสดจัดเพื่อถ่ายทอดอารมณ์ความรู้สึกภายในจิตใจ', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m4_06', 'quiz_m4_pretest', 6, 'ลัทธิเซอร์เรียลลิสม์ (Surrealism) ที่มี ซัลบาดอร์ ดาลี (Salvador Dalí) เป็นตัวแทนสำคัญ ได้รับอิทธิพลจากทฤษฎีทางจิตวิทยาของใคร?', 'ซิกมุนด์ ฟรอยด์ (Sigmund Freud - จิตวิเคราะห์และความฝัน)', 'ชาร์ลส์ ดาร์วิน (Charles Darwin - วิวัฒนาการ)', 'อัลเบิร์ต ไอน์สไตน์ (Albert Einstein - ทฤษฎีสัมพัทธภาพ)', 'จอห์น ล็อก (John Locke - ทฤษฎีความรู้)', 'A', 'Surrealism ได้รับอิทธิพลจากทฤษฎีจิตวิเคราะห์ของ Sigmund Freud มุ่งสำรวจดินแดนแห่งความฝัน ความปรารถนาลึกๆ และจิตไร้สำนึก', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m4_07', 'quiz_m4_pretest', 7, 'ศิลปะป็อปอาร์ต (Pop Art) ในช่วงทศวรรษ 1960 มีจุดเด่นในการนำสิ่งใดมาเป็นแรงบันดาลใจในการสร้างสรรค์?', 'ซากปรักหักพังของวิหารกรีกโบราณ', 'วัฒนธรรมบริโภคนิยม สื่อมวลชน โฆษณา และสินค้าอุตสาหกรรมในชีวิตประจำวัน', 'หลักธรรมคำสอนทางพุทธศาสนา', 'ทิวทัศน์ชนบทอันเงียบสงบ', 'B', 'Pop Art (เช่น ผลงานกระป๋องซุปแคมป์เบลล์ของ Andy Warhol) นำภาพสัญลักษณ์จากวัฒนธรรมป๊อป สื่อมวลชน และสินค้าตลาดบริโภคมาเป็นงานศิลปะ', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m4_08', 'quiz_m4_pretest', 8, 'คำว่า ''สื่อผสม (Mixed Media)'' ในงานทัศนศิลป์ร่วมสมัยหมายถึงข้อใด?', 'การใช้สีน้ำชนิดเดียวในการระบายภาพ', 'การผสานเทคนิค วัสดุ และสื่อมากกว่าหนึ่งชนิดเข้าด้วยกันในผลงานชิ้นเดียว', 'การวาดภาพบนกระดาษร้อยปอนด์เท่านั้น', 'การคัดลอกผลงานศิลปะโบราณด้วยคอมพิวเตอร์', 'B', 'Mixed Media คือการบูรณาการวัสดุหลากหลาย เช่น สีน้ำมัน ไม้ โลหะ ผ้า กระดาษพิมพ์ หรือวัตถุสำเร็จรูป เข้าด้วยกันในชิ้นงานศิลปะ', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m4_09', 'quiz_m4_pretest', 9, '''ศิลปะจัดวาง (Installation Art)'' มีลักษณะเฉพาะที่แตกต่างจากภาพจิตรกรรมบนผืนผ้าใบอย่างไร?', 'ต้องเป็นรูปปั้นทองเหลืองเท่านั้น', 'สร้างขึ้นเพื่อเปลี่ยนพื้นที่สามมิติ ให้ผู้ชมได้เข้าไปมีปฏิสัมพันธ์และมีประสบการณ์ร่วมกับพื้นที่นั้น', 'ต้องแขวนบนผนังในระดับสายตาเสมอ', 'ใช้เวลาก่อสร้างอย่างน้อย 10 ปี', 'B', 'Installation Art จัดวางผลงานครอบคลุมพื้นที่ว่าง (Site-specific space) เพื่อให้ผู้ชมเดินเข้าไปสัมผัสแสง เสียง พื้นผิว และประสบการณ์แบบองค์รวม', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m4_10', 'quiz_m4_pretest', 10, '''ศิลปะแนวความคิด (Conceptual Art)'' ให้คุณค่าสูงสุดกับสิ่งใดในการประเมินคุณค่างานศิลปะ?', 'ความประณีตละเอียดอ่อนของฝีมือช่าง', 'แนวความคิด (Idea/Concept) ที่อยู่เบื้องหลัง มากกว่าตัววัตถุทางกายภาพ', 'ราคาและมูลค่าของวัสดุที่นำมาใช้', 'ความเหมือนจริงของแสงเงา', 'B', 'Conceptual Art ถือว่า ''ความคิด'' คือแก่นแท้ของศิลปะ กระบวนการคิดและสาระที่สื่อสำคัญกว่าความสวยงามทางเทคนิคของวัตถุ', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m4_11', 'quiz_m4_pretest', 11, 'หลักการจัดองค์ประกอบ ''สัดส่วนทองคำ (Golden Ratio : 1 : 1.618)'' มีประโยชน์อย่างไรในการสร้างสรรค์งานทัศนศิลป์และการออกแบบ?', 'ทำให้ภาพวาดมีขนาดใหญ่ขึ้นเป็นสองเท่า', 'สร้างสัดส่วนที่มีความกลมกลืน สมดุล และให้ความรู้สึกงดงามสบายตาอย่างเป็นธรรมชาติ', 'ทำให้ผลงานประหยัดปริมาณสีที่ใช้', 'ป้องกันไม่ให้สีบนภาพวาดซีดจาง', 'B', 'Golden Ratio เป็นสัดส่วนคณิตศาสตร์ที่พบในธรรมชาติและเปลือกหอย นำมาใช้กำหนดตำแหน่งสัดส่วนให้ภาพดูสมดุลและสวยงามเป็นสากล', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m4_12', 'quiz_m4_pretest', 12, 'การใช้ ''เส้นนำสายตา (Leading Lines)'' ในงานจิตรกรรมและภาพถ่ายมีหน้าที่หลักอย่างไร?', 'แบ่งภาพออกเป็นสองส่วนเท่าๆ กันอย่างถาวร', 'นำทางดวงตาของผู้ชมให้เคลื่อนเข้าสู่จุดเด่นหรือพื้นที่สำคัญของเรื่องราวในภาพ', 'ปิดกั้นไม่ให้สายตามองเห็นจุดด้อยของงาน', 'ใช้แทนการเขียนกรอบภาพ', 'B', 'Leading Lines เช่น แนวถนน แม่น้ำ หรือเงา ทอดยาวนำสายตาผู้ชมจากขอบภาพเข้าสู่จุดศูนย์รวมความสนใจ (Focal Point)', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m4_13', 'quiz_m4_pretest', 13, 'ศิลปินเอกชาวไทยผู้ได้รับการยกย่องว่าเป็นบิดาแห่งศิลปะร่วมสมัยของไทย และเป็นผู้ก่อตั้งมหาวิทยาลัยศิลปากร คือใคร?', 'ศาสตราจารย์ศิลป์ พีระศรี (Corrado Feroci)', 'อาจารย์เฉลิมชัย โฆษิตพิพัฒน์', 'อาจารย์ถวัลย์ ดัชนี', 'สมเด็จพระเจ้าบรมวงศ์เธอ เจ้าฟ้ากรมพระยานริศรานุวัดติวงศ์', 'A', 'ศ.ศิลป์ พีระศรี ประติมากรชาวอิตาลีผู้วางรากฐานการศึกษาวิชาศิลปะสมัยใหม่ในประเทศไทยและก่อตั้งมหาวิทยาลัยศิลปากร', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m4_14', 'quiz_m4_pretest', 14, 'ผลงานจิตรกรรมของ อาจารย์ถวัลย์ ดัชนี มีเอกลักษณ์เฉพาะตัวที่โดดเด่นในข้อใด?', 'ภาพดอกไม้สีหวานสไตล์อิมเพรสชันนิสม์', 'การใช้สีดำ ขาว แดง ถ่ายทอดปรัชญาพุทธศาสนาผ่านรูปทรงสัตว์ทรงพลังและฝีแปรงฉับพลัน', 'ภาพลายเส้นการ์ตูนร่วมสมัย', 'ภาพวาดทิวทัศน์สไตล์ตะวันตกแท้', 'B', 'อ.ถวัลย์ ดัชนี ใช้พลังของปลายพู่กัน เส้นสายอันทรงพลัง และโทนสีดำ-แดง ถ่ายทอดกิเลสมนุษย์และปรัชญาพุทธศิลป์ระดับโลก', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m4_15', 'quiz_m4_pretest', 15, '''ศิลปะนามธรรม (Abstract Art)'' มีลักษณะการนำเสนอภาพอย่างไร?', 'การจำลองภาพคน สัตว์ สิ่งของอย่างสมจริงทุกประการ', 'การลดทอน ละทิ้ง หรือตัดขาดจากรูปลักษณ์ของวัตถุจริง มุ่งเน้นการสื่อสารผ่านรูปทรง สี และเส้นอย่างอิสระ', 'การวาดภาพพิมพ์เขียวทางสถาปัตยกรรม', 'การเขียนลายไทยประเพณีดั้งเดิม', 'B', 'Abstract Art ไม่มุ่งเลียนแบบสิ่งที่มองเห็นในโลกความเป็นจริง แต่ใช้ภาษาของรูปทรง สี และพื้นผิวเพื่อสื่ออารมณ์และความคิดโดยตรง', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m4_16', 'quiz_m4_pretest', 16, 'ในยุคเรเนสซองส์ (Renaissance) เทคนิค ''สฟูมาโต (Sfumato)'' ที่ เลโอนาร์โด ดา วินชี นำมาใช้ในภาพโมนาลิซา หมายถึงเทคนิคใด?', 'การเกลี่ยรอยต่อของแสงเงาให้ฟุ้งกลืนไร้รอยต่อดุจควันหมอก', 'การตัดเส้นสีดำหนาเพื่อเน้นขอบวัตถุ', 'การโรยผงทองคำลงบนพื้นผิวสีเปียก', 'การใช้มีดกรีดพื้นผิวภาพให้เป็นรอย', 'A', 'Sfumato (ภาษาสเปน/อิตาลีแปลว่า ควัน) คือการเกลี่ยสีและเงาให้ผสานกันอย่างนุ่มนวลไร้รอยตัด ทำให้ใบหน้าและแววตามีมิติสมจริงอย่างลึกลับ', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m4_17', 'quiz_m4_pretest', 17, 'กระบวนการ ''คิดเชิงออกแบบ (Design Thinking)'' ขั้นตอนใดที่เน้นการทำความเข้าใจปัญหาและความต้องการของผู้ใช้งานอย่างลึกซึ้ง?', 'ขั้น Empathize (เอาใจใส่/เข้าใจกลุ่มเป้าหมาย)', 'ขั้น Prototype (สร้างต้นแบบจำลอง)', 'ขั้น Test (ทดสอบผลลัพธ์)', 'ขั้น Production (ผลิตจำนวนมาก)', 'A', 'Empathize คือก้าวแรกของ Design Thinking ที่ผู้ออกแบบต้องเข้าไปสังเกต สัมภาษณ์ และเข้าใจความต้องการที่แท้จริงของผู้ใช้', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m4_18', 'quiz_m4_pretest', 18, '''พื้นที่ว่างเชิงบวก (Positive Space)'' และ ''พื้นที่ว่างเชิงลบ (Negative Space)'' สัมพันธ์กันอย่างไรในงานทัศนศิลป์?', 'พื้นที่เชิงบวกคือตัววัตถุหลัก ส่วนพื้นที่เชิงลบคือบริเวณว่างรอบวัตถุ ซึ่งช่วยขับเน้นจุดเด่นของกันและกัน', 'พื้นที่เชิงบวกใช้เฉพาะสีขาว พื้นที่เชิงลบใช้เฉพาะสีดำ', 'พื้นที่เชิงลบเป็นส่วนที่วาดเสีย ต้องตัดทิ้งเสมอ', 'ทั้งสองพื้นที่ไม่มีความสัมพันธ์กัน', 'A', 'Positive space คือรูปทรงของวัตถุประธาน ส่วน Negative space คือพื้นที่ว่างรอบข้าง การจัดสมดุลของทั้งสองส่วนทำให้เกิดจังหวะภาพที่ลงตัว', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m4_19', 'quiz_m4_pretest', 19, 'การใช้สีแบบ ''โทนเดียวหลากระดับ (Monochromatic Color Scheme)'' มีลักษณะการใช้สีอย่างไร?', 'การใช้สีคู่ตรงข้ามอย่างน้อย 3 คู่', 'การใช้สีเนื้อเดียว (Single Hue) แล้วแปรเปลี่ยนความสว่างและความเข้มด้วยการผสมสีขาว สีเทา หรือสีดำ', 'การใช้แม่สีปฐมภูมิ แดง เหลือง น้ำเงิน เท่านั้น', 'การใช้สีสะท้อนแสงนีออนทุกสี', 'B', 'Monochromatic คือการใช้โทนสีเดียว แต่เล่นเฉดอ่อน-แก่ (Tint and Shade) สร้างอารมณ์กลมกลืน สงบ เรียบหรู และคลาสสิก', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m4_20', 'quiz_m4_pretest', 20, 'การรู้เท่าทันทางสายตา (Visual Literacy) ในยุคดิจิทัลมีความสำคัญต่อนักเรียนในด้านใดมากที่สุด?', 'ช่วยให้โพสต์ภาพลงโซเชียลมีเดียได้ยอดไลก์สูงสุด', 'ความสามารถในการตีความ วิเคราะห์ความหมาย และรู้เท่าทันสารที่แฝงมากับภาพและสื่อดิจิทัลในสังคม', 'ความสามารถในการจดจำชื่อภาพวาดได้ทุกชิ้นในโลก', 'การเปลี่ยนอาชีพเป็นช่างภาพมืออาชีพได้ทันที', 'B', 'Visual Literacy คือทักษะการรู้เท่าทันภาพ การอ่านรหัสความหมาย การแยกแยะความจริงกับภาพลวงตา และการเข้าใจสารสื่อสารทางสายตาในยุคดิจิทัล', NULL, '2026-09-16 12:52:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m3_formative_1', 'quiz_m3_formative_elements', 1, 'ข้อใดกล่าวถึงความหมายของ ''ทัศนธาตุ'' (Visual Elements) ได้ถูกต้องที่สุด?', 'หลักการที่ใช้ในการวิจารณ์ผลงานศิลปะของศิลปิน', 'ส่วนประกอบพื้นฐานในการสร้างสรรค์งานศิลปะที่สามารถมองเห็นได้', 'อุปกรณ์และสารเคมีที่ใช้ในการผสมเนื้อสีสำหรับงานจิตรกรรม', 'ชื่อเรียกกลุ่มศิลปินยุคใหม่ที่เน้นการใช้เทคโนโลยี', 'B', 'ทัศนธาตุคือส่วนประกอบมูลฐานที่นำมารวมกันสร้างเป็นผลงานศิลปะ เช่น จุด เส้น สี รูปร่าง รูปทรง น้ำหนัก พื้นผิว และที่ว่าง', NULL, '2026-09-17 07:34:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m3_formative_2', 'quiz_m3_formative_elements', 2, 'เส้นประเภทใดให้ความรู้สึกมั่นคง แข็งแรง สง่างาม และเป็นทางการมากที่สุด?', 'เส้นคดหรือเส้นคลื่น', 'เส้นนอน', 'เส้นตั้งหรือเส้นดิ่ง', 'เส้นเฉียงหรือเส้นทแยง', 'C', 'เส้นตั้ง (Vertical Line) ให้ความรู้สึกสูงสง่า มั่นคง แข็งแรง และน่าเกรงขาม', NULL, '2026-09-17 07:34:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m3_formative_3', 'quiz_m3_formative_elements', 3, 'ความแตกต่างระหว่าง ''รูปร่าง'' (Shape) และ ''รูปทรง'' (Form) ในทางทัศนศิลป์คือข้อใด?', 'รูปร่างมี 2 มิติ ส่วนรูปทรงมี 3 มิติ มีความหนาและปริมาตร', 'รูปร่างมองเห็นด้วยตา ส่วนรูปทรงใช้มือสัมผัสได้อย่างเดียว', 'รูปร่างใช้เฉพาะงานจิตรกรรม ส่วนรูปทรงใช้เฉพาะงานสถาปัตยกรรม', 'รูปร่างไม่มีขอบเขตแน่นอน ส่วนรูปทรงมีขอบเขตเรขาคณิตเสมอ', 'A', 'รูปร่างมีความกว้างและยาว (2 มิติ) ส่วนรูปทรงมีความกว้าง ยาว ลึก/หนา (3 มิติ)', NULL, '2026-09-17 07:34:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m3_formative_4', 'quiz_m3_formative_elements', 4, 'สีคู่ตรงข้าม (Complementary Colors) ในวงจรสีข้อใดจับคู่ถูกต้อง?', 'สีแดง คู่กับ สีส้ม', 'สีเหลือง คู่กับ สีม่วง', 'สีน้ำเงิน คู่กับ สีเขียว', 'สีส้ม คู่กับ สีชมพู', 'B', 'สีคู่ตรงข้ามในวงจรสี 12 สี ได้แก่ เหลือง-ม่วง, แดง-เขียว, น้ำเงิน-ส้ม', NULL, '2026-09-17 07:34:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m3_formative_5', 'quiz_m3_formative_elements', 5, 'การจัดองค์ประกอบศิลป์แบบ ''สมดุลแบบสองข้างไม่เท่ากัน'' (Asymmetrical Balance) มีลักษณะอย่างไร?', 'ทั้งสองข้างมีรูปร่างและขนาดเหมือนกันทุกประการ', 'ไม่มีจุดเด่นในภาพเลย', 'ทั้งสองข้างมีรูปร่างต่างกันแต่ให้น้ำหนักความรู้สึกที่สมดุลกัน', 'ภาพถูกแบ่งครึ่งด้วยเส้นตรงกลางเสมอ', 'C', 'สมดุลแบบอสมมาตร ทั้งสองฝั่งมีองค์ประกอบที่แตกต่างกันแต่ถ่วงดุลน้ำหนักทางสายตาได้อย่างลงตัว', NULL, '2026-09-17 07:34:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m3_formative_6', 'quiz_m3_formative_elements', 6, 'คำว่า ''เอกภาพ'' (Unity) ในงานทัศนศิลป์มีความหมายตรงกับข้อใด?', 'ความหลากหลายของเทคนิคในการวาดภาพชิ้นเดียว', 'ความเป็นอันหนึ่งอันเดียวกันขององค์ประกอบทั้งหมดในภาพ ไม่แตกแยกกระจัดกระจาย', 'การใช้สีโทนร้อนเพียงสีเดียวในผลงาน', 'การใช้พื้นที่ว่างทั้งหมดโดยไม่มีวัตถุ', 'B', 'เอกภาพคือความกลมกลืนเป็นกลุ่มก้อนอันหนึ่งอันเดียวกันของทัศนธาตุและเนื้อหา', NULL, '2026-09-17 07:34:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m3_formative_7', 'quiz_m3_formative_elements', 7, 'การสร้าง ''จุดเด่น'' หรือ ''จุดสนใจ'' (Focal Point) ในภาพวาดนิยมใช้วิธีการใด?', 'ใช้การตัดกันของสีหรือน้ำหนักแสงเงาบริเวณจุดสำคัญ', 'ทำให้ทุกส่วนในภาพมีขนาดและความสว่างเท่ากันหมด', 'วาดรายละเอียดให้หนาแน่นทั่วทั้งภาพโดยไม่เว้นช่องว่าง', 'ใช้เฉพาะเส้นประในการร่างภาพ', 'A', 'จุดเด่นมักสร้างด้วย Contrast เช่น สีที่ตัดกัน ขนาดที่โดดเด่น หรือน้ำหนักแสงเงาที่ชัดเจน', NULL, '2026-09-17 07:34:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m3_formative_8', 'quiz_m3_formative_elements', 8, 'วรรณะของสี (Color Temperature) แบ่งออกเป็นกี่วรรณะ และสีใดอยู่ในได้ทั้งสองวรรณะ?', '2 วรรณะ (ร้อน/เย็น) โดยมีสีเหลืองและสีม่วงอยู่ได้ทั้งสองวรรณะ', '3 วรรณะ (ร้อน/กลาง/เย็น) โดยมีสีขาวและสีดำเป็นตัวเชื่อม', '2 วรรณะ (สว่าง/มืด) โดยมีสีเทาอยู่ตรงกลาง', '4 วรรณะ (ฤดูร้อน/ฤดูฝน/ฤดูหนาว/ฤดูใบไม้ผลิ)', 'A', 'วงจรสีแบ่งเป็นวรรณะร้อนและวรรณะเย็น โดยสีเหลืองและสีม่วงสามารถอยู่ได้ทั้งสองวรรณะขึ้นอยู่กับสีแวดล้อม', NULL, '2026-09-17 07:34:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m3_formative_9', 'quiz_m3_formative_elements', 9, 'พื้นผิว (Texture) ในงานจิตรกรรม 2 มิติ ที่มองเห็นว่าหยาบหรือขรุขระแต่ลูบแล้วเรียบ เรียกว่าอะไร?', 'พื้นผิวจริง (Actual Texture)', 'พื้นผิวลวงตาหรือสัมผัสด้วยสายตา (Visual/Simulated Texture)', 'พื้นผิวนามธรรม (Abstract Texture)', 'พื้นผิวประดิษฐ์ (Artificial Texture)', 'B', 'พื้นผิวลวงตา (Visual Texture) คือการเขียนภาพเลียนแบบพื้นผิวจริงโดยใช้แสงเงาและน้ำหนักสี', NULL, '2026-09-17 07:34:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m3_formative_10', 'quiz_m3_formative_elements', 10, 'หลักการทัศนียภาพ (Perspective) 1 จุดรวมสายตา เหมาะสำหรับใช้วาดภาพลักษณะใดมากที่สุด?', 'ภาพมุมมองทางเดิน ถนน หรือห้องที่มองตรงเข้าไปตรงกลาง', 'ภาพมุมตึกภายนอกที่มองเห็นสันมุมด้านหน้า', 'ภาพตึกสูงเสียดฟ้าที่มองจากมุมมองมด (Worm''s eye view)', 'ภาพลายผ้าบาติกแบบสองมิติ', 'A', '1-Point Perspective มีจุด vanishing point จุดเดียว เหมาะกับภาพทางเดิน ห้อง หรือถนนที่ลึกตรงเข้าไป', NULL, '2026-09-17 07:34:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m4_formative_1', 'quiz_m4_formative_arthistory', 1, 'ยุคฟื้นฟูศิลปวิทยาการ (Renaissance) มีจุดกำเนิดขึ้นที่ประเทศใด และเน้นคุณค่าทางความคิดแบบใด?', 'ประเทศฝรั่งเศส - เน้นความเชื่อทางศาสนาแบบสุดโต่ง', 'ประเทศอิตาลี - เน้นลัทธิมนุษยนิยม (Humanism) และวิทยาศาสตร์', 'ประเทศเยอรมนี - เน้นพลังธรรมชาติและอารมณ์ความรู้สึก', 'ประเทศอังกฤษ - เน้นการปฏิวัติอุตสาหกรรม', 'B', 'ยุคเรอเนซองส์เริ่มต้นที่เมืองฟลอเรนซ์ ประเทศอิตาลี ฟื้นฟูความรู้กรีก-โรมันโบราณ และเชิดชูมนุษยนิยม', NULL, '2026-09-17 07:34:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m4_formative_2', 'quiz_m4_formative_arthistory', 2, 'ผลงานภาพเขียน ''โมนาลิซา'' (Mona Lisa) และ ''อาหารค่ำมื้อสุดท้าย'' (The Last Supper) เป็นผลงานของศิลปินท่านใด?', 'ไมเคิลแองเจโล (Michelangelo)', 'ราฟาเอล (Raphael)', 'เลโอนาร์โด ดา วินชี (Leonardo da Vinci)', 'คาราวักโจ (Caravaggio)', 'C', 'เลโอนาร์โด ดา วินชี อัจฉริยะแห่งยุคเรอเนซองส์ ผู้เชี่ยวชาญทั้งศิลปะ วิทยาศาสตร์ และกายวิภาคศาสตร์', NULL, '2026-09-17 07:34:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m4_formative_3', 'quiz_m4_formative_arthistory', 3, 'ศิลปะบาโรก (Baroque) มีจุดเด่นสำคัญในเรื่องการแสดงออกทางทัศนศิลป์อย่างไร?', 'ความสงบนิ่ง เยือกเย็น เส้นขอบคมชัดแบบเรขาคณิต', 'การใช้แสงเงาที่ตัดกันอย่างรุนแรง (Chiaroscuro) แสดงอารมณ์ดราม่าและมีความเคลื่อนไหว', 'การตัดทอนรูปทรงจนกลายเป็นลายเส้นแบนเรียบ', 'การใช้สีพาสเทลอ่อนหวานตกแต่งพระราชวังขนาดเล็ก', 'B', 'ศิลปะบาโรกเน้นความโอ่อ่า ตระการตา ความเคลื่อนไหว และแสงเงาตัดกันรุนแรงเพื่อกระตุ้นอารมณ์', NULL, '2026-09-17 07:34:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m4_formative_4', 'quiz_m4_formative_arthistory', 4, 'ลัทธิประทับใจ (Impressionism) มีแนวคิดหลักในการสร้างสรรค์งานจิตรกรรมอย่างไร?', 'การวาดภาพในสตูดิโอโดยเน้นสัดส่วนตามหลักกายวิภาคอย่างเคร่งครัด', 'การออกไปวาดภาพกลางแจ้งเพื่อบันทึกแสงและสีที่เปลี่ยนแปลงอย่างรวดเร็วในแต่ละช่วงเวลา', 'การวาดภาพความฝันและจิตใต้สำนึกที่ไร้ตรรกะเหตุผล', 'การนำวัสดุเหลือใช้มาประกอบเป็นประติมากรรม', 'B', 'กลุ่ม Impressionists (เช่น โคลด โมเนต์) นิยมวาดภาพกลางแจ้ง (Plein Air) เพื่อจับประกายแสงและสีตามธรรมชาติ', NULL, '2026-09-17 07:34:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m4_formative_5', 'quiz_m4_formative_arthistory', 5, 'ภาพเขียนชื่อก้องโลก ''The Starry Night'' (ราตรีประดับดาว) เป็นผลงานของศิลปินคนสำคัญท่านใดในกลุ่ม Post-Impressionism?', 'วินเซนต์ แวน โก๊ะ (Vincent van Gogh)', 'ปอล เซซาน (Paul Cézanne)', 'ปอล โกแกง (Paul Gauguin)', 'อองรี มาติส (Henri Matisse)', 'A', 'วินเซนต์ แวน โก๊ะ ใช้ฝีแปรงที่รุนแรงหมุนวนและสีสันสดใสเพื่อถ่ายทอดอารมณ์ความรู้สึกภายในจิตใจ', NULL, '2026-09-17 07:34:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m4_formative_6', 'quiz_m4_formative_arthistory', 6, 'ลัทธิคิวบิสม์ (Cubism) ที่ริเริ่มโดย ปาโบล ปิกัสโซ มีเอกลักษณ์โดดเด่นในเรื่องใด?', 'การวาดภาพบุคคลที่สวยงามสมจริงเหมือนภาพถ่าย', 'การตัดทอนรูปทรงธรรมชาติให้เป็นรูปทรงเรขาคณิตและแสดงมุมมองหลายด้านพร้อมกันในภาพเดียว', 'การใช้วัสดุเรืองแสงในที่มืด', 'การใช้สีน้ำโปร่งแสงวาดภาพทิวทัศน์ชนบท', 'B', 'Cubism วิเคราะห์วัตถุแล้วแยกย่อยเป็นระนาบเรขาคณิต นำมุมมองหลายมิติมาประกอบกันบนพื้นราบ 2 มิติ', NULL, '2026-09-17 07:34:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m4_formative_7', 'quiz_m4_formative_arthistory', 7, 'ภาพ ''The Persistence of Memory'' ที่มีรูปนาฬิกาละลาย จัดอยู่ในลัทธิศิลปะใด?', 'ลัทธิเหนือจริง (Surrealism)', 'ลัทธิสำแดงพลังอารมณ์ (Expressionism)', 'ลัทธิอนาคตนิยม (Futurism)', 'ลัทธิดาดา (Dadaism)', 'A', 'ภาพนาฬิกาละลายของ ซัลวาดอร์ ดาลี (Salvador Dalí) ถ่ายทอดโลกแห่งความฝันและจิตใต้สำนึกตามแนวคิด Surrealism', NULL, '2026-09-17 07:34:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m4_formative_8', 'quiz_m4_formative_arthistory', 8, 'ป๊อปอาร์ต (Pop Art) นำแรงบันดาลใจและภาพลักษณ์มาจากสิ่งใดในการสร้างสรรค์ผลงาน?', 'ตำนานเทพปกรณัมกรีกและเรื่องเล่าในคัมภีร์ไบเบิล', 'วัฒนธรรมประชานิยม สินค้าบริโภค ป้ายโฆษณา และการ์ตูนในชีวิตประจำวัน', 'ทิวทัศน์ธรรมชาติในป่าลึกที่ไร้ผู้คน', 'โบราณคดีและภาพเขียนบนผนังถ้ำยุคก่อนประวัติศาสตร์', 'B', 'Pop Art (เช่น ผลงานของ แอนดี วอร์ฮอล) สะท้อนวัฒนธรรมบริโภคนิยม สินค้าอุปโภคบริโภค และสื่อมวลชน', NULL, '2026-09-17 07:34:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m4_formative_9', 'quiz_m4_formative_arthistory', 9, 'ศิลปินท่านใดได้รับการยกย่องให้เป็น ''บิดาแห่งศิลปะสมัยใหม่'' (Father of Modern Art)?', 'โคลด โมเนต์ (Claude Monet)', 'ปอล เซซาน (Paul Cézanne)', 'โอกุสต์ โรแดง (Auguste Rodin)', 'แจ็กสัน พอลล็อก (Jackson Pollock)', 'B', 'ปอล เซซาน เชื่อว่ารูปทรงทุกอย่างในธรรมชาติสามารถลดทอนเป็นทรงกลม ทรงกระบอก และทรงกรวย เป็นรากฐานสู่ Cubism', NULL, '2026-09-17 07:34:56');
INSERT OR REPLACE INTO "quiz_questions" ("id", "quiz_id", "question_number", "question_text", "choice_a", "choice_b", "choice_c", "choice_d", "correct_answer", "explanation", "image_url", "created_at") VALUES ('q_m4_formative_10', 'quiz_m4_formative_arthistory', 10, 'เทคนิคการสาดสี หยดสี และเหวี่ยงสีลงบนผืนผ้าใบขนาดใหญ่ (Action Painting) เป็นเอกลักษณ์ของศิลปินท่านใด?', 'แจ็กสัน พอลล็อก (Jackson Pollock)', 'มาร์ก รอทโก (Mark Rothko)', 'วาซิลี คานดินสกี (Wassily Kandinsky)', 'มาร์แซล ดูชองป์ (Marcel Duchamp)', 'A', 'แจ็กสัน พอลล็อก แห่งกลุ่ม Abstract Expressionism บุกเบิกเทคนิค Drip Painting ปลดปล่อยพลังอารมณ์ผ่านการเคลื่อนไหว', NULL, '2026-09-17 07:34:56');
